<?php
namespace Aurelle\Controllers;
use Aurelle\Database as DB;
use Aurelle\Auth;
use Aurelle\Services\Platform as P;
use Aurelle\Services\Messaging as M;
use Aurelle\Services\Documents as D;
final class WebController {
    private function render(string $page,string $title,array $data=[]): void { $user=Auth::user(); require ROOT.'/templates/layout.php'; }
    private function json(mixed $data): never { header('Content-Type: application/json'); echo json_encode($data); exit; }
    public function run(): void {
        $path=rtrim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/') ?: '/';
        if ($_SERVER['REQUEST_METHOD']==='POST') { Auth::csrf(); $this->action($path); return; }
        if ($_SERVER['REQUEST_METHOD']!=='GET') P::fail('Method not allowed.',422);
        if ($path==='/api/messages') { $u=Auth::requireUser(); $this->json(M::fetch($u['id'],(int)($_GET['conversation'] ?? 0),max(0,(int)($_GET['after'] ?? 0)),max(0,(int)($_GET['before'] ?? 0)),(string)($_GET['q'] ?? ''))); }
        if ($path==='/api/token') { $u=Auth::requireUser(); $this->json(['token'=>M::token($u['id']),'url'=>\env('WS_URL','ws://127.0.0.1:8081')]); }
        if ($path==='/api/listings') $this->json(P::search($_GET));
        if ($path==='/download') {
            $u=Auth::requireUser(); $d=D::access($u['id'],(int)($_GET['id'] ?? 0));
            header('Content-Type: '.$d['mime']); header('Content-Disposition: attachment; filename="'.preg_replace('/[^a-zA-Z0-9._ -]/','_',$d['original_name']).'"'); header('Cache-Control: private, no-store'); readfile(ROOT.'/storage/documents/'.$d['storage_name']); return;
        }
        if ($path==='/media') {
            $m=DB::one('SELECT m.*,l.status,l.seller_id,l.agent_id FROM listing_media m JOIN listings l ON l.id=m.listing_id WHERE m.id=?',[(int)($_GET['id'] ?? 0)]);
            if (!$m || !str_starts_with($m['path'],'local:')) P::fail('Media not found.',404);
            P::listing($m['listing_id'],Auth::user()['id'] ?? 0); $file=ROOT.'/storage/media/'.substr($m['path'],6);
            header('Content-Type: '.(new \finfo(FILEINFO_MIME_TYPE))->file($file)); readfile($file); return;
        }
        if ($path==='/') { $this->render('home','A considered place to call home',['properties'=>P::search([])['items'],'neighborhoods'=>DB::all('SELECT * FROM neighborhoods'),'agents'=>$this->agents()]); return; }
        if (in_array($path,['/properties','/buy','/rent'])) { $filters=$_GET; if ($path!=='/properties') $filters['purpose']=$path==='/rent'?'rent':'sale'; $this->render('properties','Exceptional homes. Your next chapter.',['search'=>P::search($filters),'filters'=>$filters,'amenities'=>DB::all('SELECT * FROM amenities'),'types'=>DB::all('SELECT * FROM property_categories')]); return; }
        if ($path==='/property') {
            $p=P::listing((int)($_GET['id'] ?? 0),Auth::user()['id'] ?? 0); $private=$p['seller_id']==(Auth::user()['id'] ?? 0) || $p['agent_id']==(Auth::user()['id'] ?? 0) || Auth::has('admin');
            if (!$private && $p['location_privacy']!=='exact') $p['address']='Exact address shared after a confirmed viewing';
            if (!$private) { if ($p['location_privacy']==='private') { $p['latitude']=null; $p['longitude']=null; } elseif ($p['location_privacy']==='approximate') { $p['latitude']=round($p['latitude'],2); $p['longitude']=round($p['longitude'],2); } }
            DB::query('INSERT INTO listing_events (listing_id,user_id,event) VALUES (?,?,"view")',[$p['id'],Auth::user()['id'] ?? null]);
            $this->render('property',$p['title'],['property'=>$p,'media'=>DB::all('SELECT * FROM listing_media WHERE listing_id=? ORDER BY is_cover DESC,sort_order,id',[$p['id']]),'amenities'=>DB::all('SELECT a.* FROM amenities a JOIN listing_amenities la ON la.amenity_id=a.id WHERE listing_id=?',[$p['id']]),'agent'=>DB::one('SELECT u.name,a.* FROM agent_profiles a JOIN users u ON u.id=a.user_id WHERE user_id=?',[$p['agent_id']]),'availability'=>DB::all('SELECT * FROM availability WHERE listing_id=? AND ends_at>UTC_TIMESTAMP() ORDER BY starts_at',[$p['id']]),'prices'=>DB::all('SELECT * FROM price_history WHERE listing_id=? ORDER BY id',[$p['id']])]); return;
        }
        if ($path==='/agents' || $path==='/agent') { $this->render('agents','People who understand home',['agents'=>$this->agents($path==='/agent'?(int)($_GET['id'] ?? 0):null),'single'=>$path==='/agent']); return; }
        if ($path==='/neighborhoods') { $this->render('neighborhoods','Find your sense of place',['neighborhoods'=>DB::all('SELECT * FROM neighborhoods')]); return; }
        if ($path==='/sell') { $this->render('sell','Every home has a story. Let’s tell yours.'); return; }
        if ($path==='/services') { $this->render('services','Considered care, at every step',['services'=>DB::all('SELECT * FROM services WHERE active=1'),'providers'=>DB::all('SELECT * FROM service_providers WHERE status="approved"')]); return; }
        if (in_array($path,['/login','/register','/forgot','/reset'])) { $this->render('auth',ucfirst(substr($path,1)),['mode'=>substr($path,1)]); return; }
        if ($path==='/submit') { $u=Auth::requireUser(); $id=(int)($_GET['id'] ?? 0); $this->render('submit','A home worth sharing',['property'=>$id?P::listing($id,$u['id'],true):null,'types'=>DB::all('SELECT * FROM property_categories'),'amenities'=>DB::all('SELECT * FROM amenities'),'selected'=>$id?array_column(DB::all('SELECT amenity_id FROM listing_amenities WHERE listing_id=?',[$id]),'amenity_id'):[]]); return; }
        if ($path==='/compare') { $ids=array_slice(array_unique(array_filter(array_map('intval',explode(',',$_GET['ids'] ?? '')))),0,4); $items=[]; foreach ($ids as $id) { try { $items[]=P::listing($id,Auth::user()['id'] ?? 0); } catch (\RuntimeException) {} } $this->render('compare','A closer look, side by side',['properties'=>$items]); return; }
        if ($path==='/dashboard') { $u=Auth::requireUser(); $this->render('dashboard','Your Veyra',['tab'=>$_GET['tab'] ?? 'overview',...$this->dashboard($u)]); return; }
        if ($path==='/admin') { $u=Auth::admin(); $this->render('admin','The estate office',$this->adminData()); return; }
        if ($path==='/admin/export') {
            $u=Auth::admin(); P::audit($u['id'],'csv_export','invoice','all'); header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename="aurelle-service-invoices.csv"'); $out=fopen('php://output','w'); fputcsv($out,['ID','Customer','Total minor units','Currency','Status']);
            foreach (DB::all('SELECT i.*,u.name FROM invoices i JOIN users u ON u.id=i.user_id ORDER BY i.id') as $r) fputcsv($out,[$r['id'],preg_match('/^[=+@-]/',$r['name'])?"'".$r['name']:$r['name'],$r['total_minor'],$r['currency'],$r['status']]); return;
        }
        $slug=ltrim($path,'/'); $c=DB::one('SELECT * FROM content WHERE slug=?',[$slug]);
        if ($c) { $this->render('content',$c['title'],['content'=>$c,'articles'=>$slug==='journal'?DB::all('SELECT * FROM content WHERE slug LIKE "journal-%"'):[]]); return; }
        P::fail('This page could not be found.',404);
    }
    private function agents(?int $id=null): array { return DB::all('SELECT u.name,a.* FROM agent_profiles a JOIN users u ON u.id=a.user_id WHERE a.approved_at IS NOT NULL AND u.suspended=0'.($id?' AND a.user_id=?':''),$id?[$id]:[]); }
    private function dashboard(array $u): array {
        $id=$u['id']; $admin=Auth::has('admin');
        return [
            'listings'=>DB::all('SELECT l.*,(SELECT COUNT(*) FROM listing_events le WHERE le.listing_id=l.id AND le.event="view") views,(SELECT COUNT(*) FROM favorites f WHERE f.listing_id=l.id) favorites_count,(SELECT COUNT(*) FROM listing_events le WHERE le.listing_id=l.id AND le.event="inquiry") inquiries FROM listings l WHERE seller_id=? OR agent_id=? ORDER BY id DESC',[$id,Auth::has('agent')?$id:0]),
            'favorites'=>DB::all('SELECT l.* FROM favorites f JOIN listings l ON l.id=f.listing_id WHERE f.user_id=? AND l.status IN ("published","under_offer")',[$id]),
            'collections'=>DB::all('SELECT DISTINCT c.* FROM collections c LEFT JOIN collection_memberships cm ON cm.collection_id=c.id WHERE c.owner_id=? OR cm.user_id=?',[$id,$id]),
            'searches'=>DB::all('SELECT * FROM saved_searches WHERE user_id=?',[$id]),
            'viewings'=>DB::all('SELECT v.*,l.title FROM viewings v JOIN listings l ON l.id=v.listing_id WHERE v.customer_id=? OR v.agent_id=? OR l.seller_id=? ORDER BY starts_at DESC',[$id,Auth::has('agent')?$id:0,$id]),
            'proposals'=>DB::all('SELECT p.*,l.title,l.seller_id,l.agent_id FROM proposals p JOIN listings l ON l.id=p.listing_id WHERE p.customer_id=? OR l.seller_id=? OR l.agent_id=? ORDER BY p.id DESC',[$id,$id,Auth::has('agent')?$id:0]),
            'conversations'=>DB::all('SELECT c.*,(SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.id AND m.id>cp.last_read_id AND m.sender_id<>cp.user_id) unread FROM conversations c JOIN conversation_participants cp ON cp.conversation_id=c.id WHERE cp.user_id=? ORDER BY c.id DESC',[$id]),
            'notifications'=>DB::all('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 50',[$id]),
            'documents'=>DB::all('SELECT DISTINCT d.* FROM documents d LEFT JOIN document_shares s ON s.document_id=d.id WHERE d.owner_id=? OR s.user_id=? ORDER BY d.id DESC',[$id,$id]),
            'leads'=>Auth::has('agent')?DB::all('SELECT l.*,u.name,u.email,p.title FROM leads l JOIN users u ON u.id=l.customer_id LEFT JOIN listings p ON p.id=l.listing_id WHERE l.agent_id=? ORDER BY l.id DESC',[$id]):[],
            'tasks'=>DB::all('SELECT * FROM tasks WHERE user_id=? ORDER BY due_at',[$id]),
            'requests'=>DB::all('SELECT r.*,s.name FROM service_requests r JOIN services s ON s.id=r.service_id WHERE r.user_id=? ORDER BY r.id DESC',[$id]),
            'invoices'=>DB::all('SELECT * FROM invoices WHERE user_id=? ORDER BY id DESC',[$id]),
            'valuations'=>DB::all('SELECT * FROM valuation_requests WHERE user_id=? OR agent_id=?',[$id,Auth::has('agent')?$id:0]),
            'application'=>DB::one('SELECT * FROM agent_profiles WHERE user_id=?',[$id]),
        ];
    }
    private function adminData(): array {
        $section=$_GET['section'] ?? 'listings'; $page=max(1,(int)($_GET['page'] ?? 1)); $offset=($page-1)*20;
        $tables=['listings'=>'listings','users'=>'users','agents'=>'agent_profiles','services'=>'service_requests','billing'=>'invoices','reports'=>'reports','reviews'=>'reviews','valuations'=>'valuation_requests','audit'=>'audit_events','content'=>'content','categories'=>'property_categories','amenities'=>'amenities','neighborhoods'=>'neighborhoods','templates'=>'notification_templates','failures'=>'delivery_failures','leads'=>'leads','viewings'=>'viewings','proposals'=>'proposals','pricing'=>'price_change_requests','providers'=>'service_providers','business'=>'business_settings','catalog'=>'services'];
        $table=$tables[$section] ?? 'listings'; $where=''; $params=[];
        if (!empty($_GET['q']) && in_array($section,['users','listings'])) { $where=' WHERE '.($section==='users'?'name':'title').' LIKE ?'; $params[]='%'.substr($_GET['q'],0,100).'%'; }
        $rows=DB::all('SELECT * FROM '.$table.$where.' LIMIT 20 OFFSET '.$offset,$params);
        return ['section'=>$section,'rows'=>$rows,'total'=>DB::one('SELECT COUNT(*) total FROM '.$table.$where,$params)['total'],'pageNumber'=>$page,'approvedAgents'=>$this->agents(),'stats'=>['Properties'=>DB::one('SELECT COUNT(*) n FROM listings')['n'],'Members'=>DB::one('SELECT COUNT(*) n FROM users')['n'],'Awaiting review'=>DB::one('SELECT COUNT(*) n FROM listings WHERE status="submitted"')['n'],'Open reports'=>DB::one('SELECT COUNT(*) n FROM reports WHERE status="open"')['n']]];
    }
    private function action(string $path): void {
        if ($path==='/login') { Auth::login($_POST['email'] ?? '',$_POST['password'] ?? ''); redirect('/dashboard'); }
        if ($path==='/register') { Auth::rate('register:'.($_SERVER['REMOTE_ADDR'] ?? ''),5,600); $id=Auth::register($_POST); session_regenerate_id(true); $_SESSION['user_id']=$id; flash('Welcome to Veyra. Your account supports both buying and selling.'); redirect('/dashboard'); }
        if ($path==='/forgot') {
            Auth::rate('reset:'.($_SERVER['REMOTE_ADDR'] ?? ''),5,600); $u=DB::one('SELECT id FROM users WHERE email=?',[strtolower(trim($_POST['email'] ?? ''))]);
            if ($u) { $token=bin2hex(random_bytes(32)); DB::query('INSERT INTO password_resets (user_id,token_hash,expires_at) VALUES (?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 MINUTE))',[$u['id'],hash('sha256',$token)]); $dir=ROOT.'/storage/mail'; if (!is_dir($dir)) mkdir($dir,0700,true); if (env('APP_ENV')==='local') file_put_contents($dir.'/reset-'.bin2hex(random_bytes(6)).'.txt',env('APP_URL').'/reset?token='.$token); DB::query('INSERT INTO delivery_failures (user_id,channel,reason) VALUES (?,"email","No mail provider configured; no email sent")',[$u['id']]); }
            flash('If this account exists, a reset was requested. Email delivery is disabled in this installation; the local operator can retrieve a private reset link.'); redirect('/forgot');
        }
        if ($path==='/reset') {
            if (strlen($_POST['password'] ?? '')<12) P::fail('Use at least 12 characters.');
            DB::transaction(function() { $r=DB::one('SELECT * FROM password_resets WHERE token_hash=? AND used_at IS NULL AND expires_at>UTC_TIMESTAMP() FOR UPDATE',[hash('sha256',$_POST['token'] ?? '')]); if (!$r) P::fail('Reset link is invalid or expired.'); DB::query('UPDATE users SET password_hash=? WHERE id=?',[password_hash($_POST['password'],PASSWORD_DEFAULT),$r['user_id']]); DB::query('UPDATE password_resets SET used_at=UTC_TIMESTAMP() WHERE user_id=?',[$r['user_id']]); DB::query('DELETE FROM realtime_tokens WHERE user_id=?',[$r['user_id']]); }); flash('Password updated.'); redirect('/login');
        }
        $u=Auth::requireUser(); $actor=(int)$u['id']; $action=$_POST['action'] ?? ''; $id=(int)($_POST['id'] ?? 0);
        if ($path==='/logout') { $_SESSION=[]; session_destroy(); redirect('/'); }
        if ($path==='/api/messages') { $this->json(M::send($actor,(int)($_POST['conversation'] ?? 0),$_POST['body'] ?? '',$_POST['key'] ?? '')); }
        if ($path==='/api/receipt') { M::receipt($actor,(int)($_POST['conversation'] ?? 0),(int)($_POST['last'] ?? 0),($_POST['read'] ?? '')==='1'); $this->json(['ok'=>true]); }
        if ($path==='/submit') { $id=P::saveListing($actor,$_POST); flash('Draft saved. Published listings require review after edits.'); redirect('/submit?id='.$id); }
        if ($path==='/favorite') { P::listing($id,$actor); if (DB::one('SELECT user_id FROM favorites WHERE user_id=? AND listing_id=?',[$actor,$id])) DB::query('DELETE FROM favorites WHERE user_id=? AND listing_id=?',[$actor,$id]); else DB::query('INSERT INTO favorites (user_id,listing_id) VALUES (?,?)',[$actor,$id]); flash('Saved homes updated.'); redirect('/dashboard?tab=favorites'); }
        if ($path==='/conversation') { $cid=M::start($actor,$id); redirect('/dashboard?tab=messages&conversation='.$cid); }
        if ($path==='/viewing') { P::book($actor,$_POST); flash('Viewing requested. Await agent confirmation.'); redirect('/dashboard?tab=viewings'); }
        if ($path==='/proposal') { P::proposal($actor,$_POST); flash('Nonbinding proposal submitted.'); redirect('/dashboard?tab=proposals'); }
        if ($path==='/valuation') { DB::query('INSERT INTO valuation_requests (user_id,address,property_type,details) VALUES (?,?,?,?)',[$actor,P::text($_POST,'address',3,255),P::text($_POST,'property_type',2,80),P::text($_POST,'details',5,5000)]); flash('Valuation consultation requested. No automated valuation has been generated.'); redirect('/dashboard?tab=listings'); }
        if ($path==='/service-request') { if (!DB::one('SELECT id FROM services WHERE id=? AND active=1',[$id])) P::fail('Service unavailable.'); DB::query('INSERT INTO service_requests (user_id,service_id,details) VALUES (?,?,?)',[$actor,$id,P::text($_POST,'details',5,5000)]); flash('Service requested. A quotation will be prepared. Online collection is disabled.'); redirect('/dashboard?tab=services'); }
        if ($path==='/dashboard/action') { $this->dashboardAction($actor,$action,$id); flash('Your changes have been saved.'); $tab=in_array($_POST['tab'] ?? '',['overview','listings','favorites','collections','searches','viewings','proposals','messages','documents','crm','services','settings','notifications'])?$_POST['tab']:'overview'; redirect('/dashboard?tab='.$tab); }
        if ($path==='/admin/action') { Auth::admin(); $this->adminAction($actor,$action,$id); flash('Administrative change saved and audited.'); redirect('/admin?section='.urlencode($_POST['section'] ?? 'listings')); }
        P::fail('Action not found.',404);
    }
    private function dashboardAction(int $a,string $action,int $id): void {
        switch ($action) {
        case 'listing_state': P::transitionListing($a,$id,$_POST['state'] ?? '',$_POST['reason'] ?? ''); break;
        case 'viewing_state': P::viewingState($a,$id,$_POST['state'] ?? ''); break;
        case 'proposal_state': P::proposalState($a,$id,$_POST['state'] ?? '',$_POST); break;
        case 'collection_create': $cid=DB::insert('INSERT INTO collections (owner_id,name) VALUES (?,?)',[$a,P::text($_POST,'name',2,100)]); DB::query('INSERT INTO collection_memberships VALUES (?,?)',[$cid,$a]); break;
        case 'collection_invite': P::collection($a,$id,true); $u=DB::one('SELECT id FROM users WHERE email=? AND suspended=0',[strtolower(trim($_POST['email'] ?? ''))]); if (!$u) P::fail('Ask the collaborator to register first.'); DB::query('INSERT IGNORE INTO collection_memberships VALUES (?,?)',[$id,$u['id']]); P::notify($u['id'],'Collection invitation','You have been invited to a shared collection.','/dashboard?tab=collections'); break;
        case 'collection_remove': P::collection($a,$id,true); $uid=(int)($_POST['user_id'] ?? 0); if ($uid===$a) P::fail('Owner membership cannot be removed.'); DB::query('DELETE FROM collection_memberships WHERE collection_id=? AND user_id=?',[$id,$uid]); DB::query('DELETE cp FROM conversation_participants cp JOIN conversations c ON c.id=cp.conversation_id WHERE c.collection_id=? AND cp.user_id=?',[$id,$uid]); break;
        case 'collection_add': P::collection($a,$id); $lid=(int)($_POST['listing_id'] ?? 0); P::listing($lid,$a); DB::query('INSERT IGNORE INTO collection_listings VALUES (?,?)',[$id,$lid]); break;
        case 'collection_comment': P::collection($a,$id); $lid=(int)($_POST['listing_id'] ?? 0); if (!DB::one('SELECT listing_id FROM collection_listings WHERE collection_id=? AND listing_id=?',[$id,$lid])) P::fail('Property is not in this collection.'); DB::query('INSERT INTO collection_comments (collection_id,listing_id,user_id,body) VALUES (?,?,?,?)',[$id,$lid,$a,P::text($_POST,'body',1,5000)]); break;
        case 'collection_chat': P::collection($a,$id); DB::transaction(function() use ($a,$id) { DB::one('SELECT id FROM collections WHERE id=? FOR UPDATE',[$id]); $c=DB::one('SELECT id FROM conversations WHERE collection_id=?',[$id]); $cid=$c['id'] ?? DB::insert('INSERT INTO conversations (collection_id,title) VALUES (?,"Shared property collection")',[$id]); foreach (DB::all('SELECT user_id FROM collection_memberships WHERE collection_id=?',[$id]) as $u) DB::query('INSERT IGNORE INTO conversation_participants (conversation_id,user_id) VALUES (?,?)',[$cid,$u['user_id']]); }); break;
        case 'search_save': $filters=[]; parse_str($_POST['filters'] ?? '',$filters); unset($filters['page']); DB::query('INSERT INTO saved_searches (user_id,name,filters) VALUES (?,?,?)',[$a,P::text($_POST,'name',2,100),json_encode(array_intersect_key($filters,array_flip(['q','purpose','type','min','max','beds','baths','area','amenity','availability','sort'])))]); break;
        case 'search_delete': DB::query('DELETE FROM saved_searches WHERE user_id=? AND id=?',[$a,$id]); break;
        case 'price_request': P::listing($id,$a,true); DB::query('INSERT INTO price_change_requests (listing_id,user_id,requested_minor,reason) VALUES (?,?,?,?)',[$id,$a,P::amount($_POST['amount'] ?? ''),P::text($_POST,'reason',5)]); break;
        case 'provider_apply': DB::query('INSERT INTO service_providers (user_id,name,category,details) VALUES (?,?,?,?)',[$a,P::text($_POST,'name',2,150),P::text($_POST,'category',2,100),P::text($_POST,'details',10)]); break;
        case 'agent_profile': if (!DB::one('SELECT user_id FROM agent_profiles WHERE user_id=?',[$a])) P::fail('Apply as an agent first.'); DB::query('UPDATE agent_profiles SET biography=?,agency=?,service_areas=?,languages=?,specialties=?,contact_preferences=?,credentials=?,verified_at=NULL WHERE user_id=?',[P::text($_POST,'biography',20),P::text($_POST,'agency',2,150),P::text($_POST,'service_areas',2,255),P::text($_POST,'languages',2,255),P::text($_POST,'specialties',2,255),P::text($_POST,'contact_preferences',2,255),P::text($_POST,'credentials',5),$a]); P::audit($a,'profile_revision','agent',$a); break;
        case 'document_upload': D::upload($a,$_FILES['file'] ?? []); break;
        case 'document_share': $d=D::access($a,$id); if ($d['owner_id']!=$a) P::fail('Only the owner can share.',403); $u=DB::one('SELECT id FROM users WHERE email=? AND suspended=0',[strtolower(trim($_POST['email'] ?? ''))]); if (!$u) P::fail('Recipient must have an account.'); DB::query('INSERT IGNORE INTO document_shares VALUES (?,?)',[$id,$u['id']]); P::audit($a,'share','document',$id,['recipient'=>$u['id']]); break;
        case 'document_revoke': $d=D::access($a,$id); if ($d['owner_id']!=$a) P::fail('Only the owner can revoke sharing.',403); DB::query('DELETE FROM document_shares WHERE document_id=? AND user_id=?',[$id,(int)$_POST['user_id']]); break;
        case 'attachment': D::upload($a,$_FILES['file'] ?? [],null,$id); break;
        case 'media_upload': $p=P::listing($id,$a,true); $doc=D::upload($a,$_FILES['file'] ?? [],$id); $d=DB::one('SELECT * FROM documents WHERE id=?',[$doc]); $kind=$_POST['kind'] ?? 'photo'; if (!in_array($kind,['photo','floorplan']) || ($kind==='photo' && !str_starts_with($d['mime'],'image/'))) P::fail('Photos must be image files.'); if (!is_dir(ROOT.'/storage/media')) mkdir(ROOT.'/storage/media',0700,true); copy(ROOT.'/storage/documents/'.$d['storage_name'],ROOT.'/storage/media/'.$d['storage_name']); $mid=DB::insert('INSERT INTO listing_media (listing_id,path,kind,sort_order) VALUES (?,?,?,?)',[$id,'local:'.$d['storage_name'],$kind,(int)($_POST['sort_order'] ?? 0)]); if (!$p['cover_url'] && $kind==='photo') DB::query('UPDATE listings SET cover_url=? WHERE id=?',['/media?id='.$mid,$id]); if (in_array($p['status'],['published','under_offer'])) { DB::query('UPDATE listings SET status="submitted" WHERE id=?',[$id]); P::listingHistory($id,$a,$p['status'],'submitted','New media requires review'); } break;
        case 'media_cover': $m=DB::one('SELECT * FROM listing_media WHERE id=?',[$id]); if (!$m || $m['kind']!=='photo') P::fail('Choose a photograph.'); P::listing($m['listing_id'],$a,true); DB::transaction(function() use ($m,$id) { DB::query('UPDATE listing_media SET is_cover=(id=?) WHERE listing_id=?',[$id,$m['listing_id']]); DB::query('UPDATE listings SET cover_url=? WHERE id=?',[str_starts_with($m['path'],'local:')?'/media?id='.$id:$m['path'],$m['listing_id']]); }); $p=P::listing($m['listing_id'],$a,true); if (in_array($p['status'],['published','under_offer'])) { DB::query('UPDATE listings SET status="submitted" WHERE id=?',[$p['id']]); P::listingHistory($p['id'],$a,$p['status'],'submitted','Cover photograph change requires review'); } break;
        case 'availability': P::listing($id,$a,true); $zone=new \DateTimeZone(P::text($_POST,'timezone')); $s=(new \DateTimeImmutable(P::text($_POST,'starts_at'),$zone))->setTimezone(new \DateTimeZone('UTC')); $end=(new \DateTimeImmutable(P::text($_POST,'ends_at'),$zone))->setTimezone(new \DateTimeZone('UTC')); if ($end<=$s || $s->getTimestamp()<time()) P::fail('Provide a future time window.'); DB::query('INSERT INTO availability (listing_id,starts_at,ends_at,open_house) VALUES (?,?,?,?)',[$id,$s->format('Y-m-d H:i:s'),$end->format('Y-m-d H:i:s'),isset($_POST['open_house'])?1:0]); break;
        case 'lead_update': if (!Auth::has('agent',$a) || !DB::one('SELECT id FROM leads WHERE id=? AND agent_id=?',[$id,$a])) P::fail('Lead access denied.',403); $stage=$_POST['stage'] ?? ''; if (!in_array($stage,['new','contacted','qualified','viewing','proposal','closed','lost'])) P::fail('Invalid stage.'); DB::query('UPDATE leads SET stage=? WHERE id=?',[$stage,$id]); P::history($a,'lead',$id,$stage); if (trim($_POST['note'] ?? '')!=='') DB::query('INSERT INTO lead_notes (lead_id,actor_id,body) VALUES (?,?,?)',[$id,$a,P::text($_POST,'note')]); break;
        case 'task_create': $due=new \DateTimeImmutable(P::text($_POST,'due_at'),new \DateTimeZone('UTC')); DB::query('INSERT INTO tasks (user_id,title,due_at) VALUES (?,?,?)',[$a,P::text($_POST,'title',2,190),$due->format('Y-m-d H:i:s')]); break;
        case 'task_complete': DB::query('UPDATE tasks SET completed_at=UTC_TIMESTAMP() WHERE id=? AND user_id=?',[$id,$a]); break;
        case 'checklist_add': $r=DB::one('SELECT p.*,l.seller_id,l.agent_id FROM proposals p JOIN listings l ON l.id=p.listing_id WHERE p.id=? AND p.status="accepted"',[$id]); if (!$r || !($r['customer_id']===$a || $r['seller_id']===$a || ($r['agent_id']===$a && Auth::has('agent',$a)))) P::fail('Checklist access denied.',403); DB::query('INSERT INTO transaction_checklists (proposal_id,title) VALUES (?,?)',[$id,P::text($_POST,'title',2,190)]); P::history($a,'proposal',$id,'milestone_added'); break;
        case 'checklist': $r=DB::one('SELECT t.*,p.customer_id,l.seller_id,l.agent_id FROM transaction_checklists t JOIN proposals p ON p.id=t.proposal_id JOIN listings l ON l.id=p.listing_id WHERE t.id=?',[$id]); if (!$r || !($r['customer_id']===$a || $r['seller_id']===$a || ($r['agent_id']===$a && Auth::has('agent',$a)))) P::fail('Checklist access denied.',403); DB::query('UPDATE transaction_checklists SET completed_at=IF(completed_at IS NULL,UTC_TIMESTAMP(),NULL) WHERE id=?',[$id]); P::history($a,'checklist',$id,'updated'); break;
        case 'agent_apply': if (DB::one('SELECT user_id FROM agent_profiles WHERE user_id=?',[$a])) P::fail('Your application already exists.'); DB::query('INSERT INTO agent_profiles (user_id,biography,agency,service_areas,languages,specialties,credentials) VALUES (?,?,?,?,?,?,?)',[$a,P::text($_POST,'biography',20),P::text($_POST,'agency',2,150),P::text($_POST,'service_areas',2,255),P::text($_POST,'languages',2,255),P::text($_POST,'specialties',2,255),P::text($_POST,'credentials',5)]); break;
        case 'settings': $zone=P::text($_POST,'timezone',1,60); if (!in_array($zone,\DateTimeZone::listIdentifiers())) P::fail('Invalid time zone.'); DB::query('UPDATE users SET timezone=?,show_presence=?,notification_preferences=? WHERE id=?',[$zone,isset($_POST['show_presence'])?1:0,json_encode(['in_app'=>isset($_POST['in_app'])]),$a]); break;
        case 'notification_read': DB::query('UPDATE notifications SET read_at=UTC_TIMESTAMP() WHERE user_id=?',[$a]); break;
        case 'report': M::access($a,$id); DB::query('INSERT INTO reports (reporter_id,conversation_id,reason) VALUES (?,?,?)',[$a,$id,P::text($_POST,'reason',5)]); break;
        case 'block': M::access($a,$id); $blocked=(int)($_POST['user_id'] ?? 0); if ($blocked===$a || !DB::one('SELECT user_id FROM conversation_participants WHERE conversation_id=? AND user_id=?',[$id,$blocked])) P::fail('Invalid participant.'); DB::query('INSERT IGNORE INTO blocks VALUES (?,?)',[$a,$blocked]); break;
        case 'support': $support=DB::one('SELECT u.id FROM users u JOIN role_memberships r ON r.user_id=u.id WHERE r.role="support" AND u.suspended=0 AND u.id<>? LIMIT 1',[$a]); if (!$support) P::fail('Support is unavailable. An administrator must assign a support account.'); $cid=DB::insert('INSERT INTO conversations (title) VALUES ("Support conversation")'); foreach ([$a,$support['id']] as $uid) DB::query('INSERT INTO conversation_participants (conversation_id,user_id,kind) VALUES (?,?,?)',[$cid,$uid,$uid===$a?'customer':'support']); break;
        case 'review': $v=DB::one('SELECT * FROM viewings WHERE id=? AND customer_id=? AND status="completed"',[$id,$a]); if (!$v) P::fail('Reviews require a completed viewing.',403); $rating=(int)($_POST['rating'] ?? 0); if ($rating<1 || $rating>5) P::fail('Choose a rating from 1 to 5.'); DB::query('INSERT INTO reviews (user_id,agent_id,viewing_id,rating,body) VALUES (?,?,?,?,?)',[$a,$v['agent_id'],$id,$rating,P::text($_POST,'body',5)]); break;
        default: P::fail('Unknown dashboard action.');
        }
    }
    private function adminAction(int $a,string $action,int $id): void {
        switch ($action) {
        case 'listing_state': P::transitionListing($a,$id,$_POST['state'] ?? '',$_POST['reason'] ?? ''); break;
        case 'assign': $agent=(int)($_POST['agent_id'] ?? 0); if (!Auth::has('agent',$agent) || !DB::one('SELECT user_id FROM agent_profiles WHERE user_id=? AND approved_at IS NOT NULL',[$agent])) P::fail('Assign an approved agent.'); DB::query('UPDATE listings SET agent_id=? WHERE id=?',[$agent,$id]); break;
        case 'agent_approve': DB::transaction(function() use ($a,$id) { if (!DB::one('SELECT user_id FROM agent_profiles WHERE user_id=? FOR UPDATE',[$id])) P::fail('Application not found.'); DB::query('UPDATE agent_profiles SET approved_at=UTC_TIMESTAMP(),reviewed_by=? WHERE user_id=?',[$a,$id]); DB::query('INSERT IGNORE INTO role_memberships VALUES (?,"agent")',[$id]); }); break;
        case 'agent_verify': if (!Auth::has('agent',$id)) P::fail('Approve the application first.'); DB::query('UPDATE agent_profiles SET verified_at=UTC_TIMESTAMP(),reviewed_by=? WHERE user_id=?',[$a,$id]); break;
        case 'suspend': if ($a===$id || Auth::has('admin',$id)) P::fail('Administrators cannot be suspended here.'); DB::query('UPDATE users SET suspended=1-suspended WHERE id=?',[$id]); DB::query('DELETE FROM realtime_tokens WHERE user_id=?',[$id]); break;
        case 'support_role': if (!DB::one('SELECT id FROM users WHERE id=?',[$id])) P::fail('Account not found.'); DB::query('INSERT IGNORE INTO role_memberships VALUES (?,"support")',[$id]); break;
        case 'role_revoke': $role=$_POST['role'] ?? ''; if (!in_array($role,['agent','support'])) P::fail('Only agent and support roles can be revoked here.'); DB::query('DELETE FROM role_memberships WHERE user_id=? AND role=?',[$id,$role]); if ($role==='agent') DB::query('UPDATE agent_profiles SET approved_at=NULL,verified_at=NULL WHERE user_id=?',[$id]); DB::query('DELETE FROM realtime_tokens WHERE user_id=?',[$id]); break;
        case 'lead_assign': $agent=(int)($_POST['agent_id'] ?? 0); if (!Auth::has('agent',$agent)) P::fail('Select an approved agent.'); DB::transaction(function() use ($a,$id,$agent) { DB::query('UPDATE leads SET agent_id=? WHERE id=?',[$agent,$id]); DB::query('INSERT INTO lead_assignment_history (lead_id,agent_id,actor_id) VALUES (?,?,?)',[$id,$agent,$a]); }); break;
        case 'viewing_state': P::viewingState($a,$id,$_POST['state'] ?? ''); break;
        case 'proposal_state': P::proposalState($a,$id,$_POST['state'] ?? '',$_POST); break;
        case 'price_review': DB::transaction(function() use ($a,$id) { $r=DB::one('SELECT * FROM price_change_requests WHERE id=? AND status="requested" FOR UPDATE',[$id]); if (!$r) P::fail('Price request is not pending.'); $state=$_POST['state'] ?? ''; if (!in_array($state,['approved','rejected'])) P::fail('Invalid decision.'); if ($state==='approved') { $l=P::listing($r['listing_id'],$a,true,true); DB::query('UPDATE listings SET price_minor=? WHERE id=?',[$r['requested_minor'],$l['id']]); DB::query('INSERT INTO price_history (listing_id,price_minor) VALUES (?,?)',[$l['id'],$r['requested_minor']]); P::listingAlert($l['id'],'Property price updated'); } DB::query('UPDATE price_change_requests SET status=?,reviewed_by=? WHERE id=?',[$state,$a,$id]); }); break;
        case 'provider_review': $state=$_POST['state'] ?? ''; if (!in_array($state,['approved','rejected','archived'])) P::fail('Invalid provider status.'); DB::query('UPDATE service_providers SET status=?,reviewed_by=? WHERE id=?',[$state,$a,$id]); break;
        case 'business': $key=P::text($_POST,'setting_key',2,100); if (!in_array($key,['business_name','contact_note','footer_description'])) P::fail('Unknown business setting.'); DB::query('UPDATE business_settings SET setting_value=? WHERE setting_key=?',[P::text($_POST,'setting_value',2,500),$key]); break;
        case 'service_catalog': DB::query('UPDATE services SET name=?,description=?,price_minor=?,active=? WHERE id=?',[P::text($_POST,'name',2,100),P::text($_POST,'description',10),P::amount($_POST['price'] ?? ''),isset($_POST['active'])?1:0,$id]); break;
        case 'neighborhood': if ($id) DB::query('UPDATE neighborhoods SET name=?,city=?,description=? WHERE id=?',[P::text($_POST,'name',2,100),P::text($_POST,'city',2,100),P::text($_POST,'description',10),$id]); else DB::query('INSERT INTO neighborhoods (name,city,description,image) VALUES (?,?,?,"/assets/favicon.svg")',[P::text($_POST,'name',2,100),P::text($_POST,'city',2,100),P::text($_POST,'description',10)]); break;
        case 'quote': P::quote($a,$id,P::amount($_POST['amount'] ?? '')); break;
        case 'payment': P::payment($a,$id,P::amount($_POST['amount'] ?? ''),P::text($_POST,'reference',3,190)); break;
        case 'refund': P::refund($a,$id,P::amount($_POST['amount'] ?? ''),P::text($_POST,'reference',3,190),P::text($_POST,'reason',5)); break;
        case 'service_state': $state=$_POST['state'] ?? ''; $r=DB::one('SELECT * FROM service_requests WHERE id=?',[$id]); $graph=['requested'=>['cancelled'],'quoted'=>['scheduled','cancelled'],'scheduled'=>['completed','cancelled'],'completed'=>[],'cancelled'=>[]]; if (!$r || !in_array($state,$graph[$r['status']])) P::fail('Invalid service transition.'); $date=null; if ($state==='scheduled') $date=(new \DateTimeImmutable(P::text($_POST,'appointment_at'),new \DateTimeZone('UTC')))->format('Y-m-d H:i:s'); DB::query('UPDATE service_requests SET status=?,appointment_at=? WHERE id=?',[$state,$date,$id]); P::history($a,'service',$id,$state); break;
        case 'valuation_assign': $agent=(int)($_POST['agent_id'] ?? 0); if (!Auth::has('agent',$agent)) P::fail('Choose an approved agent.'); DB::query('UPDATE valuation_requests SET agent_id=?,status="assigned" WHERE id=?',[$agent,$id]); break;
        case 'review_moderate': $state=$_POST['state'] ?? ''; if (!in_array($state,['approved','rejected'])) P::fail('Invalid moderation status.'); DB::query('UPDATE reviews SET status=? WHERE id=?',[$state,$id]); break;
        case 'report_review': if (!Auth::has('support',$a)) P::fail('Restricted support permission required. Ordinary administrators cannot read reported messages.',403); $r=DB::one('SELECT * FROM reports WHERE id=?',[$id]); if (!$r) P::fail('Report not found.'); P::audit($a,'reported_conversation_access','report',$id); $messages=DB::all('SELECT id,sender_id,body,created_at FROM messages WHERE conversation_id=? ORDER BY id DESC LIMIT 100',[$r['conversation_id']]); $this->render('moderation','Restricted report review',['report'=>$r,'messages'=>$messages]); exit;
        case 'report_close': if (!Auth::has('support',$a)) P::fail('Restricted support permission required.',403); DB::query('UPDATE reports SET status="closed" WHERE id=?',[$id]); break;
        case 'content': DB::query('INSERT INTO content (slug,title,body) VALUES (?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),body=VALUES(body)',[P::text($_POST,'slug',1,100),P::text($_POST,'title',2,190),P::text($_POST,'body',5,50000)]); break;
        case 'category': DB::query('INSERT INTO property_categories (name) VALUES (?)',[P::text($_POST,'name',2,80)]); break;
        case 'amenity': DB::query('INSERT INTO amenities (name,accessibility) VALUES (?,?)',[P::text($_POST,'name',2,80),isset($_POST['accessibility'])?1:0]); break;
        case 'template': DB::query('INSERT INTO notification_templates (slug,subject,body) VALUES (?,?,?) ON DUPLICATE KEY UPDATE subject=VALUES(subject),body=VALUES(body)',[P::text($_POST,'slug',2,80),P::text($_POST,'subject',2,190),P::text($_POST,'body',5)]); break;
        default: P::fail('Unknown administrative action.');
        }
        P::audit($a,$action,$_POST['section'] ?? 'admin',$id);
    }
}
